"""Testbench for the UART wrapper: drives real serial bytes at a small CLKS_PER_BIT."""
from . import fips203_oracle as O
from .vectors import test_vectors
from .rtlgen import build


def emit_uart_tb(cfg, cpb=8):
    sf, si, wf, wi = build(cfg)
    f = test_vectors()["rand0"]
    fwd, inv = O.ntt(f), O.ntt_inv(f)
    init = "\n".join(f"        vin[{i}] = {f[i]}; vfw[{i}] = {fwd[i]}; viv[{i}] = {inv[i]};"
                     for i in range(256))
    nf, ni = len(wf) + cfg.overhead, len(wi) + cfg.overhead
    return f"""\
// GENERATED by cmtz.accel.mlkem_ntt.tb_uart -- do not edit.
`timescale 1ns/1ps
module mlkem_ntt_uart_tb;
    localparam CPB = {cpb};
    reg clk27 = 0; always #5 clk27 = ~clk27;
    reg rx = 1; wire tx; wire [5:0] leds;
    mlkem_ntt_uart #(.CLKS_PER_BIT(CPB)) dut (.clk27(clk27), .rx(rx), .tx(tx), .leds(leds));
    reg [11:0] vin [0:255], vfw [0:255], viv [0:255];
    initial begin
{init}
    end
    integer errors = 0, i, n;
    reg [7:0] b, b2, b3, b4;

    task send(input [7:0] d);
        integer k;
        begin
            rx = 0; repeat (CPB) @(posedge clk27);
            for (k = 0; k < 8; k = k + 1) begin rx = d[k]; repeat (CPB) @(posedge clk27); end
            rx = 1; repeat (CPB) @(posedge clk27);
        end
    endtask
    task recv(output [7:0] d);
        integer k;
        begin
            while (tx !== 1'b0) @(posedge clk27);
            repeat (CPB + CPB / 2) @(posedge clk27);
            for (k = 0; k < 8; k = k + 1) begin d[k] = tx; repeat (CPB) @(posedge clk27); end
        end
    endtask
    task write_poly(input integer which);
        begin
            send("W");
            for (i = 0; i < 256; i = i + 1) begin send(vin[i][7:0]); send({{4'd0, vin[i][11:8]}}); end
            recv(b); if (b !== "K") begin errors = errors + 1; $display("FAIL W ack %0d", b); end
        end
    endtask
    task read_check(input integer which, input [8*10-1:0] tag);
        reg [11:0] v;
        begin
            send("R");
            for (i = 0; i < 256; i = i + 1) begin
                recv(b); recv(b2); v = {{b2[3:0], b}};
                if (which == 0 && v !== vfw[i] || which == 1 && v !== viv[i] || which == 2 && v !== vin[i]) begin
                    errors = errors + 1; if (errors < 10) $display("FAIL %0s idx %0d got %0d", tag, i, v);
                end
            end
        end
    endtask

    initial begin
        repeat (60) @(posedge clk27);
        send("P"); recv(b); recv(b2); recv(b3); recv(b4);
        if (b !== "M" || b2 !== "K" || b3 !== {cfg.lanes}) begin errors = errors + 1; $display("FAIL ping %0d %0d %0d", b, b2, b3); end
        recv(b);                                   // version byte
        write_poly(0);
        send("F"); recv(b); recv(b2); recv(b3);
        if (b !== "K" || {{b3, b2}} !== {nf}) begin errors = errors + 1; $display("FAIL F reply %0d cycles %0d", b, {{b3, b2}}); end
        read_check(0, "forward");
        send("I"); recv(b); recv(b2); recv(b3);
        if (b !== "K" || {{b3, b2}} !== {ni}) begin errors = errors + 1; $display("FAIL I reply %0d cycles %0d", b, {{b3, b2}}); end
        read_check(2, "roundtrip");
        write_poly(0);
        send("I"); recv(b); recv(b2); recv(b3);
        read_check(1, "inverse");
        send("B"); send(8'd5); recv(b); recv(b2); recv(b3); recv(b4);
        if (b !== "K" || {{b4, b3, b2}} !== 5 * {nf}) begin errors = errors + 1; $display("FAIL B reply %0d total %0d expect %0d", b, {{b4, b3, b2}}, 5 * {nf}); end
        // frequency gate: wait for two windows, then Q
        repeat (60000) @(posedge clk27);
        send("Q"); recv(b); recv(b2); recv(b3); recv(b4);
        if (b !== "K" || {{b4, b3, b2}} !== 27000) begin errors = errors + 1; $display("FAIL Q %0d count %0d", b, {{b4, b3, b2}}); end
        if (errors == 0) $display("PASS mlkem_ntt_uart lanes={cfg.lanes}");
        else $display("FAIL mlkem_ntt_uart: %0d errors", errors);
        $finish;
    end
endmodule
"""
